use crate::domains::kernel_opt::corpus::KernelRule;

pub fn entries() -> Vec<KernelRule> {
    vec![
        // ── the accelerator-backend first-tile acceptance gate: a new
        // backend must prove quality AND speed on the first real input,
        // verdict cached per machine identity, anything that fails keeps
        // the reference ─────────────────────────────────────────────────
        KernelRule {
            rule_id: "accelerator-backend-first-tile-acceptance-gate".to_string(),
            gpu_concept: "MECHANISM (accelerator-backend admission; category D — dispatch, host-orchestration, the runtime ACCEPTANCE half): a host that can execute a workload on more than one backend (a compiled accelerator program vs the reference runtime) must not adopt the fast backend on CONVERSION SUCCESS alone — the first real input is the gate: the backend must reproduce the reference result within a quality floor AND must not be meaningfully slower than the reference path, the verdict is CACHED per machine identity (machine + OS + toolchain — a later job skips the gate; a changed identity re-gates), an input above the measured conversion ceiling keeps the reference without attempting the conversion, and ANY failing arm keeps the reference backend for the job. The source's gate, verbatim (at the pin, src/localsr/core/coreml_runtime.py): \"The first real tile is a gate: Core ML must reproduce the PyTorch result on the same pixels and must not be meaningfully slower than the PyTorch MPS path. The verdict is stored per Mac, macOS version and toolchain, so later jobs skip the gate. Anything that fails keeps PyTorch.\" THE CONSTANTS: MINIMUM_PSNR = 45.0; NEURAL_ENGINE_SPEED_MARGIN = 1.3 with the energy rationale in-line (\"The Neural Engine uses far less energy than the GPU, so keep it unless the PyTorch path is clearly faster on this Mac (newer GPUs can be)\"); MAXIMUM_PIXELS = 576 * 576 (\"Converting large shapes exhausted 16 GB of memory for RRDBNet (768 px failed, 512 px was measured), so larger user tiles keep PyTorch\"). THE PER-ARCH COMPATIBILITY TABLE is measured provenance carried in-rule, never bars (\"Measured on an M1 Pro (2026-10-24): every operation of SPAN, RRDBNet and FBCNN maps to the Neural Engine, which ran them 2-3x faster than MPS fp32 with a fraction of the energy. RealPLKSR's 17x17 partial convolutions fall back to the CPU on the Neural Engine, but its Core ML GPU program still beats MPS. HAT, SwinIR and NAFNet produce broken fp16 output and SCUNet does not convert, so every other architecture keeps PyTorch.\"). THE DECISION CONTENT: (a) adoption is GATED ON THE FIRST REAL INPUT, not on a conversion/completion status — a backend that converts but serves subtly wrong pixels is exactly the failure the status-based adoption misses; (b) the gate is TWO-AXIS (quality floor + speed margin) — a correct-but-slow backend loses to the reference on a host that has the reference; the speed axis carries the energy asymmetry as a documented bias toward the efficient backend (the margin is how much slower the efficient backend may be); (c) the verdict cache is keyed by the whole machine identity, so a toolchain or OS bump re-gates — a stale acceptance never outlives the stack that produced it; (d) the shape ceiling is a MEASURED conversion-memory bound (768 failed, 512 measured), so over-ceiling inputs keep the reference by policy instead of attempting and OOMing; (e) every refusal keeps the reference — the fast path is opt-in-by-evidence, never a default. REGIME: any host with a reference implementation and a compiled/accelerated alternative (Core ML vs PyTorch MPS, a TensorRT engine vs eager CUDA, a specialized kernel suite vs the portable path, a WASM validator vs the native fixer). ANTI-REGIME: a single-backend host (no gate exists); backends whose outputs are bit-identical by construction (the quality axis collapses — keep the speed arm); batch/offline settings where a wrong answer is caught downstream anyway (the gate cost buys nothing). KINSHIP (grep-verified, do not double-count): compiled-vs-eager-per-op-exactness-admission (B337, jitengine) owns the COMPILE-TIME per-OP admission axis (which op CLASSES may join a compiled graph, keyed on numerics — no speed axis, no fallback-verdict caching, no first-real-input gate); amortized-reuse-claim-break-even-artifact (rust_perf entries_68) + the calibration-table entries_19 law own the REPORT/CALIBRATION side of runtime measurement (noise-repair + per-build persistence of calibration TABLES, not backend acceptance); graph-fallback-coverage-ladder (B336) owns the CAPACITY/coverage counting of a graph cache — THIS owns the per-machine ACCEPTANCE verdict for whole-backend adoption. PORTABLE (an acceptance-gate law: first-real-input + quality floor + speed margin + per-machine cached verdict + reference-keeps fallback, ports to any dual-backend host). NotBenchable here (the gate's cost is a first-tile forward on a real accelerator; no ML validator in this corpus). Source: HerRei/local-upscale (MIT) @ cf6f8b55f407b17141b338ba3955e337fc0f6d12 — src/localsr/core/coreml_runtime.py (module docstring + the constants block + the COMPUTE_UNITS table with its measured-provenance comment, all quoted verbatim at the pin). Batch 345 / Plan 357 / Research 389.".to_string(),
            ref_shape: "// naive: adopt the accelerator backend because it CONVERTED —\n// status-based adoption. A backend that compiles but serves subtly\n// wrong pixels (or is slower than the reference it replaced) is\n// silently adopted; nothing re-checks after a toolchain bump.\n\nenum Verdict { Accepted, Rejected }\n\nfn adopt_naive(converted_ok: bool) -> Verdict {\n    if converted_ok {\n        Verdict::Accepted // conversion success == adoption\n    } else {\n        Verdict::Rejected\n    }\n}\n\nfn run_job(input: &[u8], width: usize) -> Vec<u8> {\n    // always the accelerator once converted — even past its measured\n    // conversion ceiling, even after a toolchain update changed its\n    // numerics, even if the reference path was faster on this machine\n    accelerator_forward(input, width)\n}\n\nfn accelerator_forward(input: &[u8], width: usize) -> Vec<u8> {\n    let height = input.len() / width;\n    let mut out = vec![0u8; input.len()];\n    for y in 0..height {\n        for x in 0..width {\n            // an off-by-one tap window: subtly wrong, compiles fine\n            let mut acc = 0u32;\n            let mut n = 0u32;\n            for dy in -1i32..=1 {\n                for dx in -1i32..=1 {\n                    let ny = y as i32 + dy;\n                    let nx = x as i32 + 1 + dx;\n                    if ny >= 0 && (ny as usize) < height && nx >= 0 && (nx as usize) < width {\n                        acc += u32::from(input[ny as usize * width + nx as usize]);\n                        n += 1;\n                    }\n                }\n            }\n            out[y * width + x] = if n > 0 { (acc / n) as u8 } else { 0 };\n        }\n    }\n    out\n}\n".to_string(),
            opt_pattern: "// optimized: the first real input is the acceptance gate —\n// quality floor AND speed margin against the reference; the verdict\n// is cached per machine identity; an over-ceiling input keeps the\n// reference; every failing arm keeps the reference backend.\n\nuse std::collections::HashMap;\n\nconst MINIMUM_QUALITY: f64 = 45.0;\nconst SPEED_MARGIN: f64 = 1.3;\nconst MAXIMUM_PIXELS: usize = 64 * 64; // the measured conversion ceiling\n\n#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]\nstruct MachineIdentity {\n    backend_rev: u32,\n    os_rev: u32,\n}\n\n#[derive(Clone, Copy, PartialEq, Debug)]\nenum BackendVerdict {\n    Accepted,\n    Rejected { why: &'static str },\n}\n\nfn reference_forward(input: &[u8], width: usize) -> Vec<u8> {\n    let height = input.len() / width;\n    let mut out = vec![0u8; input.len()];\n    for y in 0..height {\n        for x in 0..width {\n            let mut acc = 0u32;\n            let mut n = 0u32;\n            for dy in -1i32..=1 {\n                for dx in -1i32..=1 {\n                    let ny = y as i32 + dy;\n                    let nx = x as i32 + dx;\n                    if ny >= 0 && (ny as usize) < height && nx >= 0 && (nx as usize) < width {\n                        acc += u32::from(input[ny as usize * width + nx as usize]);\n                        n += 1;\n                    }\n                }\n            }\n            out[y * width + x] = (acc / n) as u8;\n        }\n    }\n    out\n}\n\nfn psnr_like(reference: &[u8], candidate: &[u8]) -> f64 {\n    let mae: f64 = reference\n        .iter()\n        .zip(candidate.iter())\n        .map(|(a, b)| f64::from(a.abs_diff(*b)))\n        .sum::<f64>()\n        / reference.len().max(1) as f64;\n    if mae == 0.0 {\n        100.0\n    } else {\n        (20.0 * (255.0 / mae).log10()).min(100.0)\n    }\n}\n\nstruct Gate {\n    identity: MachineIdentity,\n    cache: HashMap<MachineIdentity, BackendVerdict>,\n}\n\nimpl Gate {\n    fn adopt_or_keep(\n        &mut self,\n        first_input: &[u8],\n        width: usize,\n        candidate_time_us: u64,\n        reference_time_us: u64,\n        candidate_fn: &dyn Fn(&[u8], usize) -> Vec<u8>,\n    ) -> BackendVerdict {\n        if let Some(v) = self.cache.get(&self.identity) {\n            return *v; // a cached verdict skips the gate entirely\n        }\n        if first_input.len() > MAXIMUM_PIXELS {\n            // over the measured conversion ceiling: keep the reference\n            // by policy instead of attempting and OOMing\n            let v = BackendVerdict::Rejected { why: \"input above the measured conversion ceiling\" };\n            self.cache.insert(self.identity, v);\n            return v;\n        }\n        let reference = reference_forward(first_input, width);\n        let candidate = candidate_fn(first_input, width);\n        let quality = psnr_like(&reference, &candidate);\n        if quality < MINIMUM_QUALITY {\n            let v = BackendVerdict::Rejected {\n                why: \"quality below the floor on the first real input\",\n            };\n            self.cache.insert(self.identity, v);\n            return v;\n        }\n        if (candidate_time_us as f64) > SPEED_MARGIN * reference_time_us as f64 {\n            let v = BackendVerdict::Rejected { why: \"meaningfully slower than the reference path\" };\n            self.cache.insert(self.identity, v);\n            return v;\n        }\n        let v = BackendVerdict::Accepted;\n        self.cache.insert(self.identity, v);\n        v\n    }\n}\n\n#[test]\nfn quality_floor_refuses_a_wrong_but_convertible_backend() {\n    let input: Vec<u8> = (0..32 * 32).map(|i| ((i * 7) % 251) as u8).collect();\n    let unfaithful = |i: &[u8], w: usize| {\n        // the same off-by-one tap window: converts fine, serves wrong\n        let height = i.len() / w;\n        let mut out = vec![0u8; i.len()];\n        for y in 0..height {\n            for x in 0..w {\n                let mut acc = 0u32;\n                let mut n = 0u32;\n                for dy in -1i32..=1 {\n                    for dx in -1i32..=1 {\n                        let ny = y as i32 + dy;\n                        let nx = x as i32 + 1 + dx;\n                        if ny >= 0 && (ny as usize) < height && nx >= 0 && (nx as usize) < w {\n                            acc += u32::from(i[ny as usize * w + nx as usize]);\n                            n += 1;\n                        }\n                    }\n                }\n                out[y * w + x] = if n > 0 { (acc / n) as u8 } else { 0 };\n            }\n        }\n        out\n    };\n    let mut gate = Gate { identity: MachineIdentity { backend_rev: 2, os_rev: 1 }, cache: HashMap::new() };\n    let v = gate.adopt_or_keep(&input, 32, 500, 900, &unfaithful);\n    assert!(\n        matches!(v, BackendVerdict::Rejected { why: \"quality below the floor on the first real input\" }),\n        \"a wrong-but-fast backend refuses on quality, got {v:?}\"\n    );\n    // the naive arm adopted the same broken backend on conversion success\n    assert!(matches!(adopt_naive(true), Verdict::Accepted));\n}\n\nfn adopt_naive(converted_ok: bool) -> BackendVerdict {\n    if converted_ok {\n        BackendVerdict::Accepted\n    } else {\n        BackendVerdict::Rejected { why: \"conversion failed\" }\n    }\n}\n\n#[test]\nfn verdict_cached_per_identity_new_identity_regates() {\n    let input: Vec<u8> = (0..16 * 16).map(|i| ((i * 3) % 253) as u8).collect();\n    let faithful = |i: &[u8], w: usize| reference_forward(i, w);\n    let mut gate = Gate { identity: MachineIdentity { backend_rev: 9, os_rev: 4 }, cache: HashMap::new() };\n    let v1 = gate.adopt_or_keep(&input, 16, 500, 900, &faithful);\n    let before = gate.cache.len();\n    let v2 = gate.adopt_or_keep(&input, 16, 500, 900, &faithful);\n    assert_eq!(v1, v2);\n    assert_eq!(gate.cache.len(), before, \"a cached verdict skips the gate\");\n    // a toolchain/OS bump is a NEW identity: it re-gates\n    gate.identity = MachineIdentity { backend_rev: 9, os_rev: 5 };\n    let v3 = gate.adopt_or_keep(&input, 16, 500, 900, &faithful);\n    assert_eq!(v3, BackendVerdict::Accepted);\n}\n".to_string(),
        },
    ]
}
